def edit_distance(word_a, word_b):
    n, m = len(word_a), len(word_b)
    edit = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                edit[i][j] = j  # Base case: if word_a is empty, insert all characters of word_b
            elif j == 0:
                edit[i][j] = i  # Base case: if word_b is empty, delete all characters of word_a
            else:
                cost = 0 if word_a[i - 1] == word_b[j - 1] else 1
                edit[i][j] = min(
                    edit[i - 1][j] + 1,        # Deletion
                    edit[i][j - 1] + 1,        # Insertion
                    edit[i - 1][j - 1] + cost  # Substitution
                )

    return edit[n][m]

