def longest_increasing_subsequence(nums):
    if not nums:
        return []
    dp = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    max_length = max(dp)
    result = []
    for i in range(len(nums) - 1, -1, -1):
        if dp[i] == max_length and (not result or nums[i] < result[-1]):
            result.append(nums[i])
            max_length -= 1
    return result[::-1]
