def spiral_order(matrix):
    result = []
    row_start, row_end = 0, len(matrix) - 1
    col_start, col_end = 0, len(matrix[0]) - 1

    while row_start <= row_end and col_start <= col_end:
        # Traverse from left to right along the top row
        for col in range(col_start, col_end + 1):
            result.append(matrix[row_start][col])
        row_start += 1

        # Traverse downwards along the right column
        for row in range(row_start, row_end + 1):
            result.append(matrix[row][col_end])
        col_end -= 1

        # Traverse from right to left along the bottom row
        if row_start <= row_end:
            for col in range(col_end, col_start - 1, -1):
                result.append(matrix[row_end][col])
            row_end -= 1

        # Traverse upwards along the left column
        if col_start <= col_end:
            for row in range(row_end, row_start - 1, -1):
                result.append(matrix[row][col_start])
            col_start += 1

    return result
