def longest_increasing_subsequence(nums):
    if not nums:
        return []

    n = len(nums)
    lis = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if nums[i] > nums[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    max_length = max(lis)
    result = []
    for i in range(n-1, -1, -1):
        if lis[i] == max_length:
            result.append(nums[i])
            max_length -= 1
    return result[::-1]

