```python
def construct_result_array(nums, k):
    if not nums:
        return []
    if len(nums) == 1:
        return [] if k == 0 else nums

    total_product = 1
    for num in nums:
        total_product *= num

    result = []
    for num in nums:
        if num == 0:
            # If there are multiple zeros, the result will be [0, 0, ..., 0] which satisfies the sum constraint
            if nums.count(0) > 1:
                return [0] * len(nums)
            # If there's exactly one zero, all other elements should be zero
            else:
                result.append(0)
        else:
            result.append(total_product // num)

    if sum(result) <= k:
        return result
    else:
        return []

