def remove_duplicates(lst):
    seen = set()
    result = []

    def is_list(item):
        return isinstance(item, list)

    def flatten(item):
        if is_list(item):
            for subitem in item:
                flatten(subitem)
        else:
            result.append(item)

    for item in lst:
        if not is_list(item):
            if item not in seen:
                seen.add(item)
                result.append(item)
