from collections import Counter

def rearrange_string(s):
    # Count the frequency of each character in the string
    char_count = Counter(s)
    # Find the character with the maximum frequency
    max_char = max(char_count, key=char_count.get)
    # If the maximum frequency is more than half the length of the string (.ceil division)
    if char_count[max_char] > (len(s) + 1) // 2:
        return "IMPOSSIBLE"
    # Initialize the result string with max_char placed at even indices
    result = [''] * len(s)
    result[::2] = [max_char] * (len(s) - char_count[max_char])
    # Fill the remaining positions with the rest of the characters
    index = 0
    for char in char_count:
        if char != max_char:
            for _ in range(char_count[char]):
                if index >= len(s):
                    index = 1  # Start filling from the first odd index if the even indices are filled
                result[index] = char
                index += 2
    return ''.join(result)

