def can_partition(nums):
    total_sum = sum(nums)
    # If total_sum is odd, it can't be partitioned into two equal parts
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: if target is 0, it's always possible (take no elements)
    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if nums[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]
