def min_window_substring(s):
    import collections
    counter = collections.Counter(s)
    required = len(counter)
    l, r = 0, 0
    formed = 0
    window_counts = {}
    ans = float('inf'), None, None
    while r < len(s):
        character = s[r]
        window_counts[character] = window_counts.get(character, 0) + 1

        if window_counts[character] == counter[character]:
            formed += 1

        while l <= r and formed == required:
            character = s[l]

            if r - l + 1 < ans[0]:
                ans = (r - l + 1, l, r)

            window_counts[character] -= 1
            if window_counts[character] < counter[character]:
                formed -= 1

            l += 1    

        r += 1    
    return ans[0]
