from collections import deque

def leastInterval(tasks, n):
    # Count the occurrences of each task
    task_count = {}
    for task in tasks:
        if task in task_count:
            task_count[task] += 1
        else:
            task_count[task] = 1

    # Max heap to store tasks by their counts
    max_heap = []
    for task, count in task_count.items():
        heapq.heappush(max_heap, (-count, task))

    total_time = 0
    while max_heap:
        temp = []
        i = 0
        # Execute tasks with maximum available count
        while i <= n:
            if max_heap:
                count, task = heapq.heappop(max_heap)
                if count != -1:
                    temp.append((count + 1, task))
            total_time += 1
            if not max_heap and not temp:
                break
            i += 1
        # Push back the executed tasks with reduced count back to the heap
        for count, task in temp:
            heapq.heappush(max_heap, (count, task))

    return total_time
