def neighbors(x, y, grid):
    # Check and return valid neighbors for a given cell
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    valid_neighbors = []
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 0:
            valid_neighbors.append((nx, ny))
    return valid_neighbors

def retrace_path(came_from, start, end):
    # Reconstruct the path from start to end
    current = end
    path = []
    while current in came_from:
        path.append(current)
        current = came_from[current]
    if path in came_from:  # If start is in came_from, append it
        path.append(current)
    return path[::-1]

def optimize_route(grid, start, end):
    # Use A* algorithm to find the shortest path
    open_set = set()
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, end)}
    open_set.add(start)

    while open_set:
        current = min(open_set, key=lambda a: f_score.get(a, 0))

        if current == end:
            return retrace_path(came_from, start, end)

        open_set.remove(current)
        for neighbor in neighbors(current[0], current[1], grid):
            tentative_g_score = g_score[current] + 1
            if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + heuristic(neighbor, end)
                if neighbor not in open_set:
                    open_set.add(neighbor)

    return []  # Return an empty list if no path found

def heuristic(a, b):
    # Heuristic function for A* algorithm
    return abs(a[0] - b[0]) + abs(a[1] - b[1])
