def max_width_of_binary_tree(arr):
    if not arr:
        return 0
    queue = [(0, 0)]  # (node's index, node's column index)
    max_width = 0
    leftmost = {}
    rightmost = {}

    while queue:
        node_index, col_index = queue.pop(0)
        if node_index % 2 == 0:
            leftmost[node_index] = col_index
        rightmost[node_index] = col_index

        if node_index * 2 + 1 < len(arr) and arr[node_index * 2 + 1] is not None:
            queue.append((node_index * 2 + 1, col_index * 2))
        if node_index * 2 + 2 < len(arr) and arr[node_index * 2 + 2] is not None:
            queue.append((node_index * 2 + 2, col_index * 2 + 1))

    for index in range(len(arr)):
        if arr[index] is not None:
            max_width = max(max_width, rightmost[index] - leftmost[index] + 1)

    return max_width

