def widthOfBinaryTree(self, arr):
    if not arr:
        return 0

    from collections import deque

    # Helper function to calculate the width of a single level
    def level_width(level):
        return level[-1][1] - level[0][1] + 1

    q = deque()
    q.append((arr[0], 0))  # (node, index)
    max_width = 0

    while q:
        level_size = len(q)
        level = []

        for _ in range(level_size):
            node, index = q.popleft()
            level.append((node, index))

            if 2 * index + 1 < len(arr):
                if arr[2 * index + 1] is not None:
                    q.append((arr[2 * index + 1], 2 * index + 1))
            if 2 * index + 2 < len(arr):
                if arr[2 * index + 2] is not None:
                    q.append((arr[2 * index + 2], 2 * index + 2))

        max_width = max(max_width, level_width(level))

    return max_width

