def largestRectangle(arr: List[int]) -> int:
    n = len(arr)
    left = []
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            left.append(stack[-1] + 1)
        else:
            left.append(0)
        stack.append(i)

    right = [0] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1] - 1
        else:
            right[i] = n - 1
        stack.append(i)

    max_area = 0
    for i in range(n):
        max_area = max(max_area, arr[i] * (right[i] - left[i] + 1))

    return max_area
```

