def evaluate_expression(expression):
    """
    Evaluates a simple mathematical expression and returns the result.

    Args:
    expression (str): A string representing a simple mathematical expression,
                      consisting of two operands and one operator ('+', '-', '*', '/').
                      Operands are assumed to be integers and non-decimal.

    Returns:
    float: The result of the evaluated expression.
    """
    # Split the expression into parts
    parts = expression.split()

    # Perform the calculation based on the operator
    if parts[1] == '+':
        return float(parts[0]) + float(parts[2])
    elif parts[1] == '-':
        return float(parts[0]) - float(parts[2])
    elif parts[1] == '*':
        return float(parts[0]) * float(parts[2])
    elif parts[1] == '/':
        return float(parts[0]) / float(parts[2])
    else:
        raise ValueError("Invalid operator.")

