def isRobotBounded(instructions):
    # Initial position and direction
    x, y = 0, 0
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # North, East, South, West
    direction_index = 0  # Start facing North

    # Execute the instructions once
    for instruction in instructions:
        if instruction == 'R':
            direction_index = (direction_index + 1) % 4  # Turn right
        elif instruction == 'L':
            direction_index = (direction_index - 1) % 4  # Turn left
        else:  # 'G' - Move forward
            dx, dy = directions[direction_index]
            x += dx
            y += dy

    # Check if the robot is back at the origin or facing a different direction
    return (x, y) == (0, 0) or direction_index != 0

