def calculate(s: str) -> int:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))

    operators = []
    values = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            start = i
            while i + 1 < len(s) and s[i + 1].isdigit():
                i += 1
            values.append(int(s[start:i + 1]))
        elif s[i] in '+-*/':
            while (operators and operators[-1] in '+-*/' and
                   precedence[s[operators[-1]]] >= precedence[s[i]]):
                apply_operator(operators, values)
            operators.append(s[i])
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

def precedence(op):
    if op in '+-':
        return 1
    elif op in '*/':
        return 2
    else:
        return 0

