def symmetric_difference(*sets):
    # Combine all sets into one, preserving the original order and duplicates
    combined_sets = []
    for s in sets:
        combined_sets.extend(s)

    # Use a dictionary to count occurrences of each element
    counts = {}
    for element in combined_sets:
        if element in counts:
            counts[element] += 1
        else:
            counts[element] = 1

    # Find elements that have an odd count, which means they are in an odd number of sets
    result = [element for element, count in counts.items() if count % 2 != 0]

    return result

