def symmetric_difference(*sets):
    # Combine all sets into a single list
    combined = []
    for s in sets:
        combined.extend(s)
    # Use a dictionary to count occurrences of each element
    count = {}
    for item in combined:
        if item in count:
            count[item] += 1
        else:
            count[item] = 1
    # Collect elements that appear exactly once
    diff = [item for item, c in count.items() if c == 1]
    # Order the result as in the first occurrence in the combined list
    result = []
    for s in sets:
        for item in s:
            if item in diff and item not in result:
                result.append(item)
    return result


