def can_form_palindrome(s: str) -> bool:
    # Helper function to count character frequency
    def count_char_frequency(s: str) -> dict:
        freq = {}
        for char in s:
            if char in freq:
                freq[char] += 1
            else:
                freq[char] = 1
        return freq

    # Get frequency of each character in the string
    char_freq = count_char_frequency(s)

    # Check the number of characters that appear an odd number of times
    odd_count = 0
    for count in char_freq.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can form a palindrome if at most one character appears an odd number of times
    return odd_count <= 1

