from typing import List

def robust_interpolation_search(array: List[int], search_key: int) -> int:
    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        # Avoid possible overflow
        pos = low + ((search_key - array[low]) * (high - low) // (array[high] - array[low]))

        if array[pos] == search_key:
            # Check for repeated elements and return the smallest index
            while pos > 0 and array[pos] == array[pos - 1]:
                pos -= 1
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1
