def evaluate_expression(expr: str) -> int:
    def parse_token(token):
        return int(token) if token.isdigit() else token

    def apply_operator(stack, operator):
        b = stack.pop()
        a = stack.pop()
        if operator == '+':
            stack.append(a + b)
        elif operator == '*':
            stack.append(a * b)

    tokens = expr.split()
    stack = []
    operators = {'+': 1, '*': 2}
    current_operator = None

    for i, token in enumerate(tokens):
        if token.isdigit():
            stack.append(parse_token(token))
        elif token in operators:
            if current_operator and operators[token] <= operators[current_operator]:
                apply_operator(stack, current_operator)
            current_operator = token
            if i < len(tokens) - 1 and tokens[i+1].isdigit():
                continue
            if stack and stack[-1] == '+':
                apply_operator(stack, stack.pop())
            current_operator = None

    while stack and current_operator:
        apply_operator(stack, current_operator)
        current_operator = None

    while len(stack) > 1:
        apply_operator(stack, stack.pop())

    return stack.pop()

