from typing import List

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def maxPossibleGCD(nums: List[int]) -> int:
    # Find the minimum number in the array
    min_num = min(nums)

    # Since the GCD of any number with 0 is 0, and we can reduce any number to 0,
    # the maximum GCD possible is at least 1.
    # Also, the GCD of the array will be at most the minimum element in the array.
    # Therefore, we need to check if all elements in the array are multiples of a certain number.
    # If they are, then we can reduce them all to that number by repeatedly subtracting the
    # minimum element from them.
    # Hence, we start from min_num and check downwards to find the greatest number
    # that can divide all elements without leaving a remainder.
    for i in range(min_num, 0, -1):
        if all(num % i == 0 for num in nums):
            return i
    return 1
