def generate_palindromes(n: int) -> List[str]:
    def helper(strlen: int) -> List[str]:
        if strlen == 0:
            return ['']
        if strlen == 1:
            return ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']
        inner = helper(strlen-2)
        ans = []
        for s in inner:
            for char in 'abcdefghijklmnopqrstuvwxyz':
