def generate_palindromes(n):
    """
    Generate all possible palindromic strings of length n using lowercase English letters.
    Return the list of these palindromic strings in lexicographical order.
    """
    if n % 2 == 0:
        half = n // 2
    else:
        half = (n // 2) + 1

    def helper(current, left):
        if len(current) == half:
            return [current] if half == 1 or current == current[::-1] else []

        results = []
        for char in "abcdefghijklmnopqrstuvwxyz":
            if len(current) < left and char <= current[left]:
                continue
            results += helper(current + char, left + 1)

        return results

    return sorted(helper("", 0))

