from typing import List

def canArrangeBalloons(n: int, balloons: List[str]) -> str:
    def is_valid(arrangement):
        for i in range(n):
            for j in range(len(balloons[0])):
                if i > 0 and arrangement[i][j] == arrangement[i - 1][j]:
                    return False
        return True

    def backtrack(start, arrangement):
        if start == n:
            if is_valid(arrangement):
                return True
            return False

        for color in balloons:
            arrangement[start] = color
            if backtrack(start + 1, arrangement):
                return True
        return False

    arrangement = [''] * n
    if backtrack(0, arrangement):
        return "YES"
    return "NO"

