    # Fill the dp array according to the recursive relation
    for i in range(1, n + 1):
        for j in range(1, x + 1):
            if arr[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]

    return dp[n][x]

