def get_bit(num: int, i: int) -> int:
    """Returns 0 if the ith bit is 0, otherwise returns 1."""
    return (num >> i) & 1

def set_bit(num: int, i: int) -> int:
    """Sets the ith bit to 1."""
    return num | (1 << i)

def clear_bit(num: int, i: int) -> int:
    """Clears the ith bit to 0."""
    return num & ~(1 << i)

def update_bit(num: int, i: int, bit: int) -> int:
    """Updates the ith bit to the given value (0 or 1)."""
    mask = ~(1 << i)
    num &= mask
    return num | (bit << i)

