def bit_manipulation(num: int, i: int, action: str, bit: int = None) -> int:
    """
    Perform a bit manipulation operation on the given integer num.

    :param num: The integer on which the bit operation will be performed.
    :param i: The index of the bit to be manipulated.
    :param action: The type of bit manipulation to be performed ('get', 'set', 'clear', or 'update').
    :param bit: The value to set the ith bit to, applicable only for the 'update' action.
    :return: An integer result of the bitwise operation or the bit value in case of 'get' action.
    """
    # Perform the operation based on the action type
    if action == 'get':
        # Shift the ith bit to the least significant bit and perform a bitwise AND
        return (num >> i) & 1
    elif action == 'set':
        # Set the ith bit to 1
        return num | (1 << i)
    elif action == 'clear':
        # Clear the ith bit to 0
        return num & ~(1 << i)
    elif action == 'update':
        # Clear the ith bit and then set it to the given 'bit' value
        return (num & ~(1 << i)) | (bit << i)
    else:
        raise ValueError("Invalid action. Supported actions are 'get', 'set', 'clear', and 'update'.")

