def is_complete_binary_tree_level_order(nodes: List[Optional[int]]) -> bool:
    # Function to find the index of the first leaf node in a level-order list
    def find_first_leaf_index(nodes: List[Optional[int]]) -> int:
        for i, node in enumerate(nodes):
            if node is None:
                return i

    # Function to check if the given level order is a complete binary tree
    def is_complete(nodes: List[Optional[int]]) -> bool:
        leaf_index = find_first_leaf_index(nodes)
        # Check if all nodes beyond the leaf_index are None
        for node in nodes[leaf_index:]:
            if node is not None:
                return False
        return True

    return is_complete(nodes)

