def can_form_palindrome(input_str: str) -> bool:
    # Normalize the string by converting to lowercase and removing non-alphabetic characters.
    normalized_str = ''.join(filter(str.isalpha, input_str)).lower()

    # Dictionary to count the occurrences of each character.
    char_count = {}

    # Count each character in the string.
    for char in normalized_str:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # A string can form a palindrome if it has at most one character that has an odd count.
    odd_count_chars = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count_chars += 1

    # For the string to be permutable to form a palindrome, there can be at most one character with an odd count.
    return odd_count_chars <= 1

