def balance_parentheses(s: str) -> str:
    balance = 0
    open_index = []

    # First pass to identify indices of unmatched open parentheses
    for i, char in enumerate(s):
        if char == '(':
            open_index.append(i)
            balance -= 1
        elif char == ')' and balance < 0:
            open_index.append(i)
            balance += 1

    # Remove unmatched parentheses with the earliest indices first
    result = list(s)
    for index in sorted(open_index, reverse=True):
        del result[index]

    return ''.join(result)

