def balance_parentheses(s: str) -> str:
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            stack.pop()
    result = []
    for char in s:
        if char == '(' and stack:
            stack.pop()
        elif char == ')' and not stack:
            continue
        result.append(char)
    return ''.join(result)

# Example usage:
print(balance_parentheses("(()())("))  # Output: "(()())"
print(balance_parentheses("))(("))      # Output: ""
print(balance_parentheses("((())("))   # Output: "(())"
