def is_bijective_pattern(pattern: str, sentence: str) -> bool:
    words = sentence.split()
    if len(pattern) != len(words):
        return False

    pattern_to_word = {}
    word_to_pattern = {}

    for p_char, word in zip(pattern, words):
        if p_char in pattern_to_word and pattern_to_word[p_char] != word:
            return False
        if word in word_to_pattern and word_to_pattern[word] != p_char:
            return False
        pattern_to_word[p_char] = word
        word_to_pattern[word] = p_char

    return True

