def floyd_warshall_algorithm(adjacency_matrix: List[List[float]]) -> List[List[float]]:
    n = len(adjacency_matrix)
    distance_matrix = adjacency_matrix

    # Iterate through all pairs of vertices
    for k in range(n):
        for i in range(n):
            for j in range(n):
                # Update the distance from i to j through k
                distance_matrix[i][j] = min(distance_matrix[i][j], distance_matrix[i][k] + distance_matrix[k][j])

    return distance_matrix


def all_pairs_shortest_path(adjacency_matrix: List[List[float]]) -> List[List[float]]:
    return floyd_warshall_algorithm(adjacency_matrix)
