def findTripletSum(arr, N, K):
    # Sort the array to facilitate the search
    arr.sort()

    # Iterate through the array and use two pointers to find the triplet
    for i in range(N - 2):
        # Initialize two pointers
        left = i + 1
        right = N - 1

        # Check all pairs with the current element
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == K:
                return "YES"
            elif current_sum < K:
                left += 1
            else:
                right -= 1

    return "NO"
