def findWinners(matches):
    # Initialize a dictionary to keep track of wins and losses for each player
    player_results = {}

    # Iterate through each match result
    for match in matches:
        player_id, opponent_id, result = match
        # Update the results for each player
        if player_id in player_results:
            player_results[player_id][0] += 1
            if result == 0:
                player_results[player_id][1] += 1
        else:
            player_results[player_id] = [1, 0 if result == 1 else 1]

        if opponent_id in player_results:
            player_results[opponent_id][0] += 1
            if result == 1:
                player_results[opponent_id][1] += 1
        else:
            player_results[opponent_id] = [1, 1 if result == 1 else 0]

    # Find players who have won all their matches
    winners = [player for player, results in player_results.items() if results[0] == results[1]]

    # Return the sorted list of winners
    return sorted(winners)

