def min_max_height_difference(heights, h):
    n = len(heights)
    min_heights = [math.inf] * n
    max_heights = [0] * n
    min_stack = []
    max_stack = []

    for i in range(n):
        while min_stack and heights[min_stack[-1]] > heights[i]:
            min_stack.pop()
        if min_stack:
            min_heights[i] = heights[min_stack[-1]]
        else:
            min_heights[i] = -math.inf
        min_stack.append(i)

    for i in range(n-1, -1, -1):
        while max_stack and heights[max_stack[-1]] < heights[i]:
            max_stack.pop()
        if max_stack:
            max_heights[i] = heights[max_stack[-1]]
        else:
            max_heights[i] = math.inf
        max_stack.append(i)

    left, right = 0, 0
    max_length = 0

    while right < n:
        if max_heights[left] - min_heights[left] <= h:
            max_length = max(max_length, right - left + 1)
            right += 1
        else:
            left += 1

