```python
def atbash_cipher(text: str) -> str:
    # Define the mapping for the Atbash cipher
    upper_mapping = {chr(i): chr(155 - i) for i in range(65, 91)}
    lower_mapping = {chr(i): chr(109 - i) for i in range(97, 123)}

    # Combine the mappings into a single dictionary
    mapping = {**upper_mapping, **lower_mapping}

    # Encode the text using the Atbash cipher
    encoded_text = ''.join(mapping.get(char, char) for char in text)

    return encoded_text
