def is_valid_matrix(m, n, matrix):
    # Check rows from left to right
    for i in range(m):
        for j in range(1, n):
            if matrix[i][j] < matrix[i][j - 1]:
                return False

    # Check columns from top to bottom
    for j in range(n):
        for i in range(1, m):
            if matrix[i][j] < matrix[i - 1][j]:
                return False

    return True

