```python
def subsequence_with_sum(arr, n, x):
    # Create a 2D array (n+1) x (x+1) initialized to False
    dp = [[False for _ in range(x+1)] for _ in range(n+1)]

    # Initialize the dp array for zero sum (always possible)
    for i in range(n+1):
        dp[i][0] = True

    # Fill the dp array
    for i in range(1, n+1):
        for j in range(1, x+1):
            if arr[i-1] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # The answer is in dp[n][x]
    return dp[n][x]

