from collections import OrderedDict

def first_non_repeated(string):
    # Use OrderedDict to remember the order of characters
    char_count = OrderedDict()

    # Count the occurrences of each character
    for char in string:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with a single occurrence
    for char, count in char_count.items():
        if count == 1:
            return char

    # Return None if no non-repeated character is found
    return None
