def two_sum(numbers, target):
    # Create a dictionary to store the numbers and their indices
    num_dict = {}
    # Iterate over the list of numbers
    for i, num in enumerate(numbers):
        # Calculate the complement number that would add up to the target
        complement = target - num
        # Check if the complement is already in the dictionary
        if complement in num_dict:
            # If found, return the indices of the complement and the current number
            return [num_dict[complement], i]
        # If not found, add the number and its index to the dictionary
        num_dict[num] = i
    # If no solution is found, return an empty list (though the problem guarantees one solution)
    return []
