def find_path(maze):
    rows, cols = len(maze), len(maze[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and maze[x][y] == 0

    def dfs(x, y, path):
        if x == rows - 1 and y == cols - 1:
            return True
        maze[x][y] = 1  # Mark the cell as visited
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and dfs(nx, ny, path + [(nx, ny)]):
                return True
        maze[x][y] = 0  # Backtrack
        return False

    return [(0, 0)] + dfs(0, 0, [(0, 0)]) and dfs(0, 0, [(0, 0)])
