def minMeetingRooms(intervals):
    if not intervals:
        return 0
    # Create two lists to store start and end times
    start = sorted([i[0] for i in intervals])
    end = sorted([i[1] for i in intervals])
    # Initialize variables
    end_index = 0
    max_rooms = 0
    room_count = 0
    # Iterate over intervals
    for i in range(len(intervals)):
        # If the current meeting starts before the earliest ending meeting
        if start[i] < end[end_index]:
            # Increase the room count
            room_count += 1
            # Update the maximum number of rooms needed
            max_rooms = max(max_rooms, room_count)
        else:
            # If a meeting has ended, decrease the room count
            room_count -= 1
            # Move the end_index to the next meeting that has ended
            end_index += 1
    return max_rooms
