def min_operations(nums):
    while len(nums) > 1:
        min_index = nums.index(min(nums))
        if min_index == 0:
            nums[0] += nums[1]
            nums.pop(1)
        elif min_index == len(nums) - 1:
            nums[-2] += nums[-1]
            nums.pop(-1)
        else:
            nums[min_index-1] += nums[min_index] + nums[min_index+1]
            nums.pop(min_index+1)
            nums.pop(min_index)
    return len(nums) - 1

