from typing import List

def comb_sort(arr: List[int]) -> List[int]:
    # Initialize the gap size to the length of the array
    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while (gap > 1) or sorted:
        # Calculate the next gap value
        if gap > 1:
            gap = int(gap / shrink_factor)

        # Initialize sorted to False so we can check if any swaps happened
        sorted = True

        # Compare elements with the current gap and swap if necessary
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False

    return arr

