    # Building the graph
    graph = {course: [] for course in set(prerequisite[0] for prerequisite in prerequisites) | set(prerequisite[1] for prerequisite in prerequisites)}
    indegree = {course: 0 for course in graph}

    for course, prerequisite in prerequisites:
        graph[prerequisite].append(course)
        indegree[course] += 1

    # Topological Sort
    queue = [course for course in graph if indegree[course] == 0]
    topologically_sorted_courses = []

    while queue:
        course = queue.pop(0)
        topologically_sorted_courses.append(course)

        for next_course in graph[course]:
            indegree[next_course] -= 1
            if indegree[next_course] == 0:
                queue.append(next_course)

    # Check if target course is in the topologically sorted list
    return target_course in topologically_sorted_courses
