def fast_power(base: int, exponent: int, mod: int) -> int:
    result = 1
    base = base % mod
    while exponent > 0:
        if (exponent % 2) == 1:  # If exponent is odd, multiply base with result
            result = (result * base) % mod
        exponent = exponent >> 1  # Divide exponent by 2
        base = (base * base) % mod  # Square the base
    return result

def secure_modular_exponentiation(base: int, exponent: int, mod: int) -> int:
    if mod == 1:
        return 0
    return fast_power(base, exponent, mod)
