def merge_dictionaries(dict1, dict2, keys):
    # Create a new dictionary to store the merged results
    merged_dict = {}

    # Iterate through the list of keys to consider for merging
    for key in keys:
        # Check if the key exists in either dictionary
        if key in dict2:
            # If the key exists in dict2, prefer the value from dict2
            merged_dict[key] = dict2[key]
        elif key in dict1:
            # If the key exists only in dict1, add it to the merged dictionary
            merged_dict[key] = dict1[key]

