def find_longest_non_decreasing_subsequence(sequence: List[int]) -> int:
    if not sequence:
        return 0

    # Initialize a list to store the length of the longest subsequence ending at each index
    lengths = [1] * len(sequence)

    # Update the lengths list by comparing each element with all previous elements
    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[i] >= sequence[j]:
                lengths[i] = max(lengths[i], lengths[j] + 1)

    # The result is the maximum value in the lengths list
    return max(lengths)

