def is_balanced(s: str) -> bool:
    # Define the pairs of matching brackets
    brackets = {'(': ')', '{': '}', '[': ']'}
    # Initialize a stack to keep track of opening brackets
    stack = []
    # Iterate through each character in the string
    for char in s:
        # If it's an opening bracket, push it onto the stack
        if char in brackets:
            stack.append(char)
        # If it's a closing bracket
        elif char in brackets.values():
            # If the stack is empty or the brackets don't match, return False
            if not stack or brackets[stack.pop()] != char:
                return False
    # If the stack is empty, all brackets were matched; return True
    # If not, there are unmatched opening brackets
    return not stack
