from collections import defaultdict, deque

def findItinerary(tickets):
    # Create a graph to represent the airports
    graph = defaultdict(deque)

    # Sort the tickets lexicographically and push them into the graph
    for src, dest in sorted(tickets):
        graph[src].appendleft(dest)

    itinerary = []

    # Depth-first search function to construct the itinerary
    def dfs(node):
        while graph[node]:
            dfs(graph[node].pop())
        itinerary.appendleft(node)

    dfs("JFK")
    return itinerary

