def find_duplicates(lst: list) -> dict:
    # Create a dictionary to store the indices of each element
    indices = {}

    # Iterate over the list and populate the dictionary with indices
    for index, value in enumerate(lst):
        if value in indices:
            indices[value].append(index)
        else:
            indices[value] = [index]

    # Filter out non-duplicates by checking if the list of indices has more than one element
    duplicates = {key: value for key, value in indices.items() if len(value) > 1}

    return duplicates
