def duplicate_characters(s: str) -> dict:
    # Create a dictionary to store the frequency of each character
    char_freq = {}

    # Convert the string to lowercase to make the function case-insensitive
    s = s.lower()

    # Iterate over each character in the string
    for char in s:
        # If the character is already in the dictionary,increment its count
        if char in char_freq:
            char_freq[char] += 1
        # If the character is not in the dictionary,add it with a count of 1
        else:
            char_freq[char] = 1

    # Create a new dictionary to store character frequencies that appear more than once
    duplicates = {}
    for char, freq in char_freq.items():
        if freq > 1:
            duplicates[char] = freq

    return duplicates
