def most_frequent_element(input_list):
    # Check if the input is a list
    if not isinstance(input_list, list):
        raise TypeError("Input must be a list.")

    # Verify that all elements in the list are integers
    for element in input_list:
        if not isinstance(element, int):
            raise ValueError("All elements in the list must be integers.")

    # Dictionary to count the frequency of each element
    frequency_dict = {}

    # Count the frequency of each element
    for element in input_list:
        if element in frequency_dict:
            frequency_dict[element] += 1
        else:
            frequency_dict[element] = 1

    # Determine the element with the highest frequency
    max_frequency = max(frequency_dict.values())
    elements_with_max_frequency = [key for key, value in frequency_dict.items() if value == max_frequency]

    # Return the smallest element among those with the highest frequency
    return min(elements_with_max_frequency)

