def current_borrowed_books(logs):
    # Dictionary to keep track of the borrow count of each book
    borrow_count = {}

    # Process each log entry
    for log in logs:
        action, book_id = log.split()
        book_id = int(book_id)

        if action == "B":
            # If the book is not already borrowed, initialize its count to 1
            if book_id not in borrow_count:
                borrow_count[book_id] = 1
            else:
                # If the book is already borrowed, increment the count
                borrow_count[book_id] += 1
        elif action == "R":
            # If the book exists in the borrow count, decrement the count
            if book_id in borrow_count:
                borrow_count[book_id] -= 1
                # If the count drops to 0, remove the book from the dictionary
                if borrow_count[book_id] == 0:
                    del borrow_count[book_id]

    # Extract the keys (book IDs) from the dictionary and sort them in ascending order
    current_borrowed = sorted(borrow_count.keys())
    return current_borrowed
