class Solution:
    def min_block_swaps(self, n, arr):
        def find_cycles(arr, n):
            visited = [False] * n
            cycles = 0

            for i in range(n):
                if not visited[i]:
                    cycle_length = 0
                    x = i

                    while not visited[x]:
                        visited[x] = True
                        x = arr.index(arr[x])
                        cycle_length += 1

                    if cycle_length > 0:
                        cycles += (cycle_length - 1)

            return cycles

        def get_new_index(arr, n):
            s = sorted(range(n), key=arr.__getitem__)
            return s[:]

        arr = get_new_index(arr, n)
        return find_cycles(arr, n)
