class Solution:
    def sumSubarrayMins(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(arr)
        stack = []
        left = [0] * n
        right = [n - 1] * n

        for i in range(n):
            while stack and arr[stack[-1]] > arr[i]:
                stack.pop()
            if stack:
                left[i] = i - stack[-1] - 1
            stack.append(i)

        stack = []
        for i in range(n - 1, -1, -1):
            while stack and arr[stack[-1]] >= arr[i]:
                stack.pop()
            if stack:
                right[i] = stack[-1] - i - 1
            stack.append(i)

        result = 0
        for i in range(n):
            result = (result + arr[i] * (left[i] + 1) * (right[i] + 1)) % MOD

        return result
