def is_valid_expression(expression: str) -> bool:
    # We will use a stack to keep track of opening characters
    stack = []
    # Mapping of closing characters to their corresponding opening characters
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in expression:
        # If the character is an opening character, push it onto the stack
        if char in mapping.values():
            stack.append(char)
        # If the character is a closing character
        elif char in mapping:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening character, return False
            if not stack or mapping[char] != stack.pop():
                return False

    # If the stack is empty, all opening characters had matching closing characters
    return not stack
