def lengthOfLongestSubstring(s):
    # [5] 使用一个字典来存储字符最后一次出现的位置
    char_to_index = {}
    # [3] 初始化变量来记录当前窗口的左边界和最大不重复子字符串的长度
    start = 0
    max_length = 0

    # [2] 遍历字符串
    for end in range(len(s)):
        # [4] 如果当前字符已经在字典中并且在当前窗口内
        if s[end] in char_to_index and char_to_index[s[end]] >= start:
            # [6] 更新窗口的左边界为当前字符上一次出现的位置的下一个位置
            start = char_to_index[s[end]] + 1
        else:
            # [7] 计算当前窗口的长度并更新最大长度
            max_length = max(max_length, end - start + 1)

        # [8] 更新当前字符在字典中的位置
        char_to_index[s[end]] = end

    return max_length
