def longest_common_substring(str1: str, str2: str) -> Tuple[int, str]:
    # Initialize the matrix to store lengths of longest common suffixes
    n, m = len(str1), len(str2)
    length_matrix = [[0] * (m + 1) for _ in range(n + 1)]
    max_length = 0  # Variable to store the length of the maximum length substring
    end_index = 0  # To store the ending index of the longest common substring in str1

    # Build the length matrix
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                length_matrix[i][j] = length_matrix[i - 1][j - 1] + 1
                if length_matrix[i][j] > max_length:
                    max_length = length_matrix[i][j]
                    end_index = i - 1

    # Extract the longest common substring from str1
    longest_substring = str1[end_index - max_length + 1:end_index + 1] if max_length > 0 else ""

    return (max_length, longest_substring)
