def is_anagram(s1, s2):
    # Handling potential case sensitivity
    s1 = s1.lower()
    s2 = s2.lower()

    # Check if both strings have the same number of characters
    if len(s1) != len(s2):
        return False

    # Use a dictionary to count occurrences of each character in s1
    char_count = {}
    for char in s1:
        char_count[char] = char_count.get(char, 0) + 1

    # Decrease the count for each character found in s2
    for char in s2:
        if char in char_count:
            char_count[char] -= 1
            # If count goes negative, s2 has more of char than s1
            if char_count[char] < 0:
                return False
        else:
            # If char not found in char_count, it means s2 has extra char
            return False

    # If all counts are zero, s2 is an anagram of s1
