class Solution:
    def minTransformationSteps(self, start, end, wordPairs):
        # Convert list of tuples to a dictionary
        # for easier lookup
        word_dict = {}
        for word1, word2 in wordPairs:
            if word1 not in word_dict:
                word_dict[word1] = set()
            if word2 not in word_dict:
                word_dict[word2] = set()
            word_dict[word1].add(word2)
            word_dict[word2].add(word1)

        # Initialize the queue for BFS
        # and a set to keep track of visited nodes
        queue = [(start, 1)]  # (current word, current step count)
        visited = set(start)

        while queue:
            current_word, steps = queue.pop(0)

            # If the current word is the end word, return the step count
            if current_word == end:
                return steps

            # Try changing one character in the current word
            for i in range(len(current_word)):
                for char in 'abcdefghijklmnopqrstuvwxyz':
                    new_word = current_word[:i] + char + current_word[i+1:]
                    if new_word in word_dict and new_word not in visited:
                        visited.add(new_word)
                        queue.append((new_word, steps + 1))

        # If no transformation sequence is found, return -1
        return -1
