def min_obstacle_path(grid: List[List[int]]) -> int:
    n = len(grid)
    direction = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    dist = [[float('inf')] * n for _ in range(n)]
    dist[0][0] = 0
    q = deque([(0, 0)])

    while q:
        i, j = q.popleft()
        for x, y in direction:
            ni, nj = i + x, j + y
            if 0 <= ni < n and 0 <= nj < n:
                if grid[ni][nj] == 1 and dist[ni][nj] > dist[i][j] + 1:
                    dist[ni][nj] = dist[i][j] + 1
                    q.append((ni, nj))
                elif grid[ni][nj] == 0 and dist[ni][nj] > dist[i][j]:
                    dist[ni][nj] = dist[i][j]
                    q.append((ni, nj))

    return dist[n-1][n-1]
