class Solution:
    def canArrange(self, nums: List[int], k: int) -> bool:
        # Create a list to count the remainders when each number is divided by k
        remainder_counts = [0] * k

        # Count the remainders
        for num in nums:
            remainder_counts[num % k] += 1

        # Check if the remainder counts are symmetric around k/2
        for i in range(k // 2 + 1):
            if i == 0 or i == k - i:
                # For remainder 0 and k, the count must be even
                if remainder_counts[i] % 2 != 0:
                    return False
            else:
                # For other remainders, the counts must be equal
                if remainder_counts[i] != remainder_counts[k - i]:
                    return False

        return True
