def alternate_chars(s1, s2):
    result = []
    len_s1 = len(s1)
    len_s2 = len(s2)
    min_length = min(len_s1, len_s2)

    # Alternating characters from both strings
    for i in range(min_length):
        result.append(s1[i])
        result.append(s2[i])

    # Append remaining characters from the longer string
    if len_s1 > len_s2:
        result.extend(s1[min_length:])
    else:
        result.extend(s2[min_length:])

    return ''.join(result)
