from collections import deque

def minStepsToTarget(board, source, target):
    rows, cols = len(board), len(board[0])
    directions = [(2, 1), (1, 2), (-1, 2), (-2, 1), (-2, -1), (-1, -2), (1, -2), (2, -1)]
    source_blocked, target_blocked = board[source[0]][source[1]] == -1, board[target[0]][target[1]] == -1

    if source_blocked or target_blocked:
        return -1

    visited = {source}
    queue = deque([(source[0], source[1], 0)])

    while queue:
        x, y, step = queue.popleft()
        if (x, y) == target:
            return step

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and board[nx][ny] != -1 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, step + 1))

    return -1
