def merge lists(list1, list2):
    # Initialize an empty list to store the merged results
    merged = []
    # Determine the maximum length of the two lists
    max_length = max(len(list1), len(list2))
    # Iterate up to the maximum length
    for i in range(max_length):
        # Append elements from list1 if the index is within its bounds
        if i < len(list1):
            if i < len(list2):
                # Concatenate strings from both lists if both indices are valid
                merged.append(list1[i] + list2[i])
            else:
                # Append element from list1 if list2 is shorter
                merged.append(list1[i])
