# Define the function robot_simulation
def robot_simulation(width, height, commands, start_position, start_orientation):
    # Possible orientations and their corresponding movement directions
    directions = {'N': (-1, 0), 'S': (1, 0), 'E': (0, 1), 'W': (0, -1)}

    # Start from the initial position and orientation
    x, y = start_position
    orientation = start_orientation

    # Process each command
    for command in commands:
        if command == 'F':
            # Calculate the next position based on current orientation
            dx, dy = directions[orientation]
            next_x, next_y = x + dx, y + dy
            # Check if the new position is within the grid boundaries
            if 0 <= next_x < width and 0 <= next_y < height:
                x, y = next_x, next_y
        elif command == 'L':
            # Change orientation counterclockwise
            if orientation == 'N':
                orientation = 'W'
            elif orientation == 'W':
                orientation = 'S'
            elif orientation == 'S':
                orientation = 'E'
            elif orientation == 'E':
                orientation = 'N'
        elif command == 'R':
            # Change orientation clockwise
            if orientation == 'N':
                orientation = 'E'
            elif orientation == 'E':
                orientation = 'S'
            elif orientation == 'S':
                orientation = 'W'
            elif orientation == 'W':
                orientation = 'N'

    # Return the final position and orientation
    return (x, y, orientation)

# Example usage
