def find_smallest_missing_positive(nums):
    n = len(nums)
    has_one = False

    # Check if 1 is present in the array, if not, then 1 is the smallest missing positive
    for num in nums:
        if num == 1:
            has_one = True
            break

    if not has_one:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1s
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 1

    # Use index mapping to mark the presence of elements
    for i in range(n):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # The first positive index + 1 indicates the smallest missing positive
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1
