```python
def find_smallest_missing_positive(nums: list) -> int:
    # Step 1: Segregate positive numbers from non-positive numbers
    shift = segregate(nums)
    nums = nums[shift:]

    # Step 2: Use the index as a hash key and number sign as a presence detector
    for i in range(len(nums)):
        if abs(nums[i]) - 1 < len(nums) and nums[abs(nums[i]) - 1] > 0:
            nums[abs(nums[i]) - 1] = -nums[abs(nums[i]) - 1]

    # Step 3: The first positive index + 1 indicates the missing smallest positive number
    for i in range(len(nums)):
        if nums[i] > 0:
            return i + 1 + shift

    # If all indexed numbers are negative, the missing smallest positive number is the next number
    return len(nums) + 1 + shift

def segregate(nums: list) -> int:
    j = 0
    for i in range(len(nums)):
        if nums[i] <= 0:
            nums[i], nums[j] = nums[j], nums[i]
            j += 1
    return j
```

