    if not arr:
        return 0

    left, count = 0, {}
    max_len = 0

    for right, num in enumerate(arr):
        count[num] = count.get(num, 0) + 1

        while len(count) > 2:
            count[arr[left]] -= 1
            if count[arr[left]] == 0:
                del count[arr[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

