def find_potential_duplicates(users: list[dict]) -> list[tuple[int, int]]:
    # Collections to store names and emails with their corresponding user IDs
    name_dict = {}
    email_dict = {}

    # Iterate over the list of users
    for user in users:
        user_id = user['id']
        name = user['name']
        email = user['email']

        # Add user ID to the name dictionary if the name already exists
        if name in name_dict:
            name_dict[name].append(user_id)
        else:
            name_dict[name] = [user_id]

        # Add user ID to the email dictionary if the email already exists
        if email in email_dict:
            email_dict[email].append(user_id)
        else:
            email_dict[email] = [user_id]

    # List to store potential duplicate pairs
    potential_duplicates = []

    # Check for potential duplicates in the name dictionary
    for ids in name_dict.values():
        if len(ids) > 1:
            for i in range(len(ids)):
                for j in range(i + 1, len(ids)):
                    # Add tuple to the list with sorted IDs
                    potential_duplicates.append(tuple(sorted((ids[i], ids[j]))))

    # Check for potential duplicates in the email dictionary
    for ids in email_dict.values():
        if len(ids) > 1:
            for i in range(len(ids)):
                for j in range(i + 1, len(ids)):
                    # Add tuple to the list with sorted IDs
                    potential_duplicates.append(tuple(sorted((ids[i], ids[j]))))

    # Return list of potential duplicate pairs
    return potential_duplicates
