def longest_substring_with_constraints(s: str, k: int) -> int:
    from collections import defaultdict

    # Helper function to find the longest substring with at most k distinct characters
    def at_most_k_distinct_substring(s, k):
        if k == 0:
            return 0
        count = defaultdict(int)
        left = 0
        right = 0
        max_length = 0

        while right < len(s):
            count[s[right]] += 1
            while len(count) > k:
                count[s[left]] -= 1
                if count[s[left]] == 0:
                    del count[s[left]]
                left += 1
            max_length = max(max_length, right - left + 1)
            right += 1

        return max_length

    # Find the longest substring with exactly k distinct characters by subtracting the longest substring with k-1 distinct characters
    def exactly_k_distinct_substring(s, k):
        return at_most_k_distinct_substring(s, k) - at_most_k_distinct_substring(s, k - 1)

    return at_most_k_distinct_substring(s, k)

