    def canBeFormedWord(self, char_count, word_count):
        for char, count in char_count.items():
            if word_count[char] < count:
                return False
        return True

    def countCharacters(self, words: list[str], chars: str) -> int:
        total_length = 0
        char_count = {}
        for char in chars:
            char_count[char] = char_count.get(char, 0) + 1

