def first_unique_char(s):
    # Dictionary to store the count of each character
    char_count = {}

    # First pass: count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first character with a count of one
    for char in s:
        if char_count[char] == 1:
            return char

    # If no unique character is found, return a specific message
    return "No unique character found"

