def max_ones_index(arr: List[int]) -> int:
    if 0 not in arr:
        return -1

    max_length = 0
    max_index = -1
    current_length = 0
    last_zero_index = -1

    for i in range(len(arr)):
        if arr[i] == 1:
            current_length += 1
        else:
            if current_length + (i - last_zero_index) > max_length:
                max_length = current_length + (i - last_zero_index)
                max_index = last_zero_index
            current_length = 0
            last_zero_index = i

    # Check the case where the last element is 0
    if arr[-1] == 1 and current_length + (len(arr) - 1 - last_zero_index) > max_length:
        max_index = last_zero_index

