def calculate_frequency(numbers):
    # 统计每个数字的频率
    frequency = {}
    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    # 将字典转换为列表，按照 frequency 和 number 排序
    frequency_list = [(number, freq) for number, freq in frequency.items()]
    frequency_list.sort(key=lambda x: (-x[1], x[0]))

    return frequency_list
