def optimized_combination(n: int, r: int) -> int:
    if n < 0 or r < 0:
        raise ValueError("n and r must be non-negative integers")
    if r > n:
        return 0
    # Edge cases where r is 0 or r is n
    if r == 0 or r == n:
        return 1

    # Initialize a 2D list for memoization
    comb = [[0 for _ in range(r+1)] for _ in range(n+1)]

    # Populate the comb table
    for i in range(n+1):
        for j in range(min(i, r)+1):
            if j == 0 or j == i:
                comb[i][j] = 1
            else:
                comb[i][j] = comb[i-1][j-1] + comb[i-1][j]

    return comb[n][r]
