import heapq

def min_time_to_reach_end(heights, k):
    n = len(heights)
    if n == 1:
        return 0
    queue = [(0, 0)]  # (time, current_index)
    visited = set()

    while queue:
        time, index = heapq.heappop(queue)
        if index == n - 1:
            return time
        if index in visited:
            continue
        visited.add(index)

        for next_index in range(max(0, index - k), min(n, index + k + 1)):
            if heights[next_index] <= heights[index]:
                heapq.heappush(queue, (time + 1, next_index))

    return -1

