def is_balanced(expression):
    # Initialize a stack to keep track of opening brackets
    stack = []
    # Define a dictionary to map closing brackets to their corresponding opening brackets
    matching_brackets = {')': '(', '}': '{', ']': '['}

    # Iterate over each character in the expression
    for char in expression:
        # If the character is an opening bracket, push it onto the stack
        if char in matching_brackets.values():
            stack.append(char)
        # If the character is a closing bracket
        elif char in matching_brackets:
            # If the stack is empty or the top of the stack does not match the corresponding opening bracket, return False
            if not stack or stack[-1] != matching_brackets[char]:
                return False
            # Otherwise, pop the top of the stack
            stack.pop()

    # If the stack is empty, all brackets were balanced; otherwise, they were not
    return len(stack) == 0
```

