def is_balanced(expression):
    """
    Determines if the brackets in the expression are balanced.

    Args:
    expression (str): The string containing the brackets to be checked.

    Returns:
    bool: True if the brackets are balanced, False otherwise.
    """
    # Stack to keep track of opening brackets
    stack = []
    # Dictionary to hold matching pairs of brackets
    brackets = {'(': ')', '{': '}', '[': ']'}

    for char in expression:
        # If the character is an opening bracket, push to stack
        if char in brackets:
            stack.append(char)
        # If the character is a closing bracket
        elif char in brackets.values():
            # If stack is empty or top of stack doesn't match the corresponding opening bracket, return False
            if not stack or brackets[stack.pop()] != char:
                return False
    # If stack is empty, brackets are balanced
    return not stack

