def eliminate_adjacent_duplicates(s):
    # Check if the string has adjacent duplicates
    def has_adjacent_duplicates(s):
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                return True
        return False

    # Helper function to perform the elimination
    def eliminate(s):
        if not s or not has_adjacent_duplicates(s):
            return s
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                return eliminate(s[:i] + s[i + 2:])

    return eliminate(s)

