def merge_sorted_logs(logs: List[List[Tuple[int, int]]]) -> List[Tuple[int, int]]:
    """
    Merges multiple sorted lists of log entries based on their timestamps into a single sorted list.
    """
    min_heap = []
    result = []

    # Initialize the min heap with the first element of each list
    for i in range(len(logs)):
        if logs[i]:
            heapq.heappush(min_heap, (logs[i][0][0], i, 0))

    # Merge the lists
    while min_heap:
        timestamp, index, entry_index = heapq.heappop(min_heap)
        result.append((timestamp, index + 1))
        if entry_index + 1 < len(logs[index]):
            next_entry = logs[index][entry_index + 1]
            heapq.heappush(min_heap, (next_entry[0], index, entry_index + 1))

    return result
