To solve this problem, we can use the Breadth-First Search (BFS) algorithm. BFS is suitable for finding the shortest path in an unweighted grid because it explores all nodes at the present depth level before moving on to nodes at the next depth level.

Here's the implementation of the `min_steps` function using BFS:

```python
from collections import deque

def min_steps(grid):
    m, n = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the start and target positions
    start = None
    target = None
    for i in range(m):
        for j in range(n):
            if grid[i][j] == "S":
                start = (i, j)
            elif grid[i][j] == "T":
                target = (i, j)

    if not start or not target:
        return -1

    # Initialize the queue for BFS and the visited set
    queue = deque([start])
    visited = set([start])
    steps = 0

    while queue:
        level_size = len(queue)
        for _ in range(level_size):
            x, y = queue.popleft()
            if (x, y) == target:
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0 and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        steps += 1

    return -1

