```python
def calculate_scores(n, logs, query_intervals):
    # 创建一个字典来存储每个玩家在每个时间点的得分
    player_scores = {}

    # 遍历所有的日志，更新 player_scores
    for timestamp, player_id, score in logs:
        if player_id not in player_scores:
            player_scores[player_id] = {}
        if timestamp not in player_scores[player_id]:
            player_scores[player_id][timestamp] = 0
        player_scores[player_id][timestamp] += score

    # 计算每个查询区间内每个玩家的得分总和
    result = []
    for start_time, end_time in query_intervals:
        interval_scores = {}
        for player_id in player_scores:
            total_score = 0
            for t in range(start_time, end_time + 1):
                if t in player_scores[player_id]:
                    total_score += player_scores[player_id][t]
            if total_score > 0:
                interval_scores[player_id] = total_score
        result.append(interval_scores)

    return result

