def firstUniqChar(s: str) -> int:
    char_count = {}

    # First pass: count the occurrences and record the first occurrence index
    for i, char in enumerate(s):
        if char in char_count:
            char_count[char][0] += 1
        else:
            char_count[char] = [1, i]

    # Second pass: find the first character with a count of one
    for char in s:
        if char_count[char][0] == 1:
            return char_count[char][1]

    # If no unique character is found, return -1 (or any other indicator)
    return -1

