def minDifference(N, arr):
    total_sum = sum(arr)
    dp = [[False for _ in range(total_sum // 2 + 1)] for _ in range(N + 1)]

    # Initialize the dp array
    for i in range(N + 1):
        dp[i][0] = True

    # Fill the dp array
    for i in range(1, N + 1):
        for j in range(1, total_sum // 2 + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Find the maximum sum that can be partitioned
    max_sum = 0
    for j in range(total_sum // 2, -1, -1):
        if dp[N][j]:
            max_sum = j
            break

    # Return the minimal difference
    return total_sum - 2 * max_sum
