def cluster_consecutive_sequences(numbers):
    if not numbers:
        return []

    def within_one(a, b):
        return abs(a - b) == 1

    clusters = []
    stack = []
    numbers.sort()

    for num in numbers:
        if not stack or within_one(stack[-1], num):
            stack.append(num)
        else:
            clusters.append(stack.copy())
            stack = [num]

    if stack:
