def isPalindromePermutation(str: str) -> bool:
    str = str.replace(" ", "")  # Remove spaces
    char_count = {}  # Dictionary to count character frequencies

    # Count each character's frequency
    for char in str:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    odd_count = 0  # Counter for characters with odd frequency

    # Check the frequency counts
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False

    return True
