def max_distinct_chars_in_substring(s: str, k: int) -> int:
    if k > len(s):
        return 0

    char_count = {}
    max_distinct = 0
    left = 0

    for right in range(len(s)):
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_distinct = max(max_distinct, len(char_count))

    return max_distinct

