```python
def segregate(nums: list[int]) -> int:
    j = 0
    for i in range(len(nums)):
        if nums[i] <= 0:
            nums[i], nums[j] = nums[j], nums[i]
            j += 1
    return j

def findMissingPositive(nums: list[int], start: int) -> int:
    for i in range(start, len(nums)):
        index = abs(nums[i]) - 1
        if index >= start and nums[index] > 0:
            nums[index] = -nums[index]
    for i in range(start, len(nums)):
        if nums[i] > 0:
            return i + 1
    return len(nums) + 1

def smallest_missing_positive(nums: list[int]) -> int:
    size = segregate(nums)
    return findMissingPositive(nums, size)
```

