def count_unique_paths(m: int, n: int) -> int:
    if m < 1 or n < 1:
        return 0

    # Create a 2D array to store the number of unique paths to each cell
    paths = [[0 for _ in range(n)] for _ in range(m)]

    # Initialize the first row and first column
    for i in range(m):
        paths[i][0] = 1
    for j in range(n):
        paths[0][j] = 1

    # Fill in the rest of the paths array using the dynamic programming approach
    for i in range(1, m):
        for j in range(1, n):
            paths[i][j] = paths[i-1][j] + paths[i][j-1]

    # The bottom-right corner will have the total number of unique paths
    return paths[m-1][n-1]

