def convert_ipv4_to_int(ipv4_str):
    """
    Converts a string representation of an IPv4 address into its corresponding Integer representation.
    If the input string is not a valid IPv4 address, raises a ValueError.
    """
    pieces = ipv4_str.split('.')
    if len(pieces) != 4:
        raise ValueError('Invalid IPv4 address')

    result = 0
    for piece in pieces:
        if not piece.isdigit():
            raise ValueError('Invalid IPv4 address')
        num = int(piece)
        if num < 0 or num > 255:
            raise ValueError('Invalid IPv4 address')
        result = (result << 8) + num

    return result

