def can_partition(arr, n, sum_s, target_sum, lookup):
    if n == 0:
        return abs(sum_s - (target_sum - sum_s))
    if lookup[n][sum_s] != -1:
        return lookup[n][sum_s]
    lookup[n][sum_s] = min(can_partition(arr, n - 1, sum_s, target_sum, lookup), can_partition(arr, n - 1, sum_s + arr[n - 1], target_sum, lookup))
    return lookup[n][sum_s]

def minPartitionDifference(arr, n):
    total_sum = sum(arr)
    lookup = [[-1 for _ in range(total_sum + 1)] for _ in range(n + 1)]
    return can_partition(arr, n, 0, total_sum, lookup)
