def reorder_list(initial_list, order_by):
    # Create a mapping of elements in initial_list to their order
    order_map = {x: i for i, x in enumerate(initial_list)}
    # Filter order_by to include only elements present in initial_list
    valid_order = [x for x in order_by if x in order_map]
    # Sort initial_list based on the order in valid_order
    sorted_list = sorted(initial_list, key=lambda x: (x in valid_order, valid_order[order_map[x]] if x in valid_order else len(order_by)))
    return sorted_list

