def minPartitionDifference(arr, n):
    total_sum = sum(arr)
    dp = [[False] * (total_sum + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True
    for i in range(1, n + 1):
        for s in range(1, total_sum + 1):
            dp[i][s] = dp[i - 1][s]
            if arr[i - 1] <= s:
                dp[i][s] |= dp[i - 1][s - arr[i - 1]]
    possible_sums = [s for s in range(total_sum // 2 + 1) if dp[n][s]]
    closest_sum = min(possible_sums, key=lambda x: abs(x - (total_sum - x)))
    return abs(total_sum - 2 * closest_sum)

