def find_lowest_cost_path(graph, start, end):
    import heapq

    # Priority queue to store nodes to be visited
    priority_queue = []
    heapq.heappush(priority_queue, (0, start, [start]))

    # Dictionary to store the shortest path to each node
    shortest_path = {start: 0}

    while priority_queue:
        (cost, current, path) = heapq.heappop(priority_queue)

        if current == end:
            return path

        for neighbor, neighbor_cost in graph.get(current, []):
            new_cost = cost + neighbor_cost
            if neighbor not in shortest_path or new_cost < shortest_path[neighbor]:
                shortest_path[neighbor] = new_cost
                new_path = list(path)
                new_path.append(neighbor)
                heapq.heappush(priority_queue, (new_cost, neighbor, new_path))

    return None
