def length_of_longest_substring(word: str) -> int:
    if not word:
        return 0

    max_length = 0
    start = 0
    used_chars = {}

    for end, char in enumerate(word):
        if char in used_chars and start <= used_chars[char]:
            start = used_chars[char] + 1
        else:
            max_length = max(max_length, end - start + 1)

        used_chars[char] = end

    return max_length
