def build_graph(edg):
    graph = {i: [] for i in range(len(edg)) + 1}
    for u, v, w in edg:
        graph[u].append((v, w))
    return graph

def dijkstra(graph, source):
    n = len(graph) - 1
    distance = [float('inf')] * (n + 1)
    prev = [None] * (n + 1)
    distance[source] = 0

    pq = [(0, source)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > distance[u]:
            continue
        for v, w in graph[u]:
            if distance[u] + w < distance[v]:
                distance[v] = distance[u] + w
                prev[v] = u
                heapq.heappush(pq, (distance[v], v))

    return distance, prev

def reconstruct_path(prev, target):
    path = []
    while target is not None:
        path.append(target)
        target = prev[target]
    path.reverse()
    return path

def shortest_path(n, edges, source, targets):
    graph = build_graph(edges)
    distance, prev = dijkstra(graph, source)

    result = []
    for target in targets:
        if distance[target] == float('inf'):
            result.append(-1)
        else:
            result.append(distance[target])

    return result
