from typing import List, Tuple

def find_uncovered_point(rectangles: List[Tuple[int, int, int, int]]) -> Tuple[int, int]:
    # Assuming we start from the origin (0, 0)
    x, y = 0, 0
    # Check if this point is covered by any rectangle
    for rect in rectangles:
        x1, y1, x2, y2 = rect
        if x1 <= x <= x2 and y1 <= y <= y2:
            # If the point is covered, move slightly to the right and up
            x += 1
            y += 1
            # Reset the point to a larger offset to avoid overlapping with previous rectangles
            x = max(x, x1)
            y = max(y, y1)
            break
    else:
        return x, y

    return x, y

def is_uncovered_point(rectangles: List[Tuple[int, int, int, int]]) -> str:
    uncovered_point = find_uncovered_point(rectangles)
    if uncovered_point:
        return "YES"
    else:
        return "NO"

