def is_anagram_of_palindrome(s: str) -> bool:
    # Create a dictionary to count the occurrences of each character
    char_count = {}
    for char in s:
        if char.isalpha():
            char_count[char] = char_count.get(char, 0) + 1

    # Check the number of characters with odd counts
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    # A string can be rearranged into a palindrome if it has at most one character with an odd count
    return odd_count <= 1
