def prime_factors(n):
    def is_prime(number):
        if number <= 1:
            return False
        for i in range(2, int(number ** 0.5) + 1):
            if number % i == 0:
                return False
        return True

    factors = []
    for num in range(2, n + 1):
        if n % num == 0 and is_prime(num):
            count = 0
            while n % num == 0:
                count += 1
                n = n // num
            factors.append(f"{num}^{count}")

    return " * ".join(factors)

