def iterative_binomial_coefficient(n: int, k: int) -> int:
    if k > n - k:
        k = n - k  # Take advantage of property C(n, k) == C(n, n-k)

    # Initialize a list to store binomial coefficients
    row = [1] * (k + 1)
    for i in range(1, n - k + 1):
        # Calculate the current binomial coefficient in a bottom-up manner
        for j in range(k, 0, -1):
            row[j] += row[j - 1]

    return row[k]
