def count_subarrays_with_product_less_than_k(arr, k):
    # Check if k is less than or equal to 1, in which case no product can be less than k
    if k <= 1:
        return 0

    left = 0
    product = 1
    count = 0

    for right in range(len(arr)):
        product *= arr[right]
        while product >= k:
            product //= arr[left]
            left += 1
        count += right - left + 1

    return count

