from typing import List

def count_unique_elements_in_range(arr: List[int], L: int, R: int) -> int:
    # Helper function to find the first element greater than or equal to L
    def binary_search_left(arr, L):
        low, high = 0, len(arr) - 1
        while low < high:
            mid = (low + high) // 2
            if arr[mid] < L:
                low = mid + 1
            else:
                high = mid
        return low if arr[low] >= L else -1

    # Helper function to find the first element greater than R
    def binary_search_right(arr, R):
        low, high = 0, len(arr) - 1
        while low < high:
            mid = (low + high) // 2
            if arr[mid] > R:
                high = mid - 1
            else:
                low = mid
        return high if arr[high] <= R else -1

    # Find the starting and ending indices of elements in the range [L, R]
    start = binary_search_left(arr, L)
    end = binary_search_right(arr, R)

    # Check if the range is valid and contains elements
    if start == -1 or end == -1 or start > end:
        return 0

    # Use a set to track unique elements in the range [start, end]
    unique_elements = set(arr[start:end + 1])
    return len(unique_elements)

