def read_decompressed_data(filename: str) -> bytes:
    try:
        with bz2.open(filename, 'rb') as file:
            return file.read()
    except FileNotFoundError:
        print("File not found.")
    except PermissionError:
        print("Permission denied.")
    except Exception as e:
        print(f"An error occurred: {e}")
    return b""

def process_data(data: bytes, filename: str) -> bool:
    write_compressed_data(data, filename)
    decompressed_data = read_decompressed_data(filename)
    return decompressed_data == data
